//! Translations for messages with values. The English template is the key.

macro_rules! formats {
    ($($english:tt => ($russian:literal, $czech:literal),)+) => {
        macro_rules! ru_template {
            $(($english) => { $russian };)+
            ($missing:literal) => { compile_error!(concat!("Missing format translation for: ", $missing)) };
        }

        #[cfg(target_os = "macos")]
        macro_rules! cs_template {
            $(($english) => { $czech };)+
            ($missing:literal) => { compile_error!(concat!("Missing Czech format translation for: ", $missing)) };
        }
    };
}

